<?php require_once 'includes/functions.php';$u=login_required();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();db()->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$u['user_id']]);flash('Notifications marked as read.');go('notifications.php');}$s=db()->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$s->execute([$u['user_id']]);$ns=$s->fetchAll();$title='Notifications';require 'includes/header.php';?><h1>Notifications</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="btn light">Mark all read</button></form><section class="panel"><?php if(!$ns):?><p>No notifications yet.</p><?php endif;?><?php foreach($ns as $n):?><article class="notice"><strong><?=e($n['message'])?></strong><small><?=e($n['created_at'])?> · <?=e($n['type'])?> · <?=$n['is_read']?'Read':'Unread'?></small></article><?php endforeach;?></section><?php require 'includes/footer.php';?>